    public class GerenciaAssistenciaTecnicaContextSeed
    {
        public static async Task SeedAsync(GerenciaAssistenciaTecnicaContext gerenciaAssistenciaTecnicaContext)
        {
            try
            {
                // TODO: Only run this if using a real database
                gerenciaAssistenciaTecnicaContext.Database.Migrate();

                if (!gerenciaAssistenciaTecnicaContext.Estados.Any())
                {
                    gerenciaAssistenciaTecnicaContext.Estados.AddRange(
                        GetPreconfiguredEstados());

                    await gerenciaAssistenciaTecnicaContext.SaveChangesAsync();
                }

                if (!gerenciaAssistenciaTecnicaContext.Cidades.Any())
                {
                    gerenciaAssistenciaTecnicaContext.Cidades.AddRange(
                        GetPreconfiguredCidades());

                    await gerenciaAssistenciaTecnicaContext.SaveChangesAsync();
                }

                if (!gerenciaAssistenciaTecnicaContext.Users.Any())
                {
                    gerenciaAssistenciaTecnicaContext.Users.AddRange(
                        GetPreconfiguredUsers());

                    await gerenciaAssistenciaTecnicaContext.SaveChangesAsync();
                }

                if (!gerenciaAssistenciaTecnicaContext.Claims.Any())
                {
                    gerenciaAssistenciaTecnicaContext.Claims.AddRange(
                        GetPreconfiguredClaims());

                    await gerenciaAssistenciaTecnicaContext.SaveChangesAsync();
                }

                await GrantAllFunctionalAccessToGustavoAsync(gerenciaAssistenciaTecnicaContext);

                if (!gerenciaAssistenciaTecnicaContext.EntradaAssistenciaStatus.Any())
                {
                    gerenciaAssistenciaTecnicaContext.EntradaAssistenciaStatus.AddRange(
                        GetPreconfiguredEntradaAssistenciaStatus());

                    await gerenciaAssistenciaTecnicaContext.SaveChangesAsync();
                }

                if (!gerenciaAssistenciaTecnicaContext.Cores.Any())
                {
                    gerenciaAssistenciaTecnicaContext.Cores.AddRange(
                        GetPreconfiguredCor());

                    await gerenciaAssistenciaTecnicaContext.SaveChangesAsync();
                }

            }
            catch (System.Exception ex)
            {

                throw;
            }
        }

        private static async Task GrantAllFunctionalAccessToGustavoAsync(
            GerenciaAssistenciaTecnicaContext context)
        {
            var gustavo = await context.Users
                .SingleOrDefaultAsync(user => user.UserName.ToLower() == "gustavo");

            if (gustavo == null)
            {
                return;
            }

            var adminUserId = new Guid("4a1947ec-099c-4532-8105-64cf8c8b4b94");
            var adminClaimTypes = GetPreconfiguredClaims()
                .Where(claim => claim.UserId == adminUserId)
                .Select(claim => claim.ClaimType)
                .Distinct()
                .ToList();
            var gustavoClaims = await context.Claims
                .Where(claim => claim.UserId == gustavo.UserId)
                .ToListAsync();
            var claimsChanged = false;

            foreach (var claimType in adminClaimTypes)
            {
                var matchingClaims = gustavoClaims
                    .Where(claim => string.Equals(
                        claim.ClaimType,
                        claimType,
                        StringComparison.OrdinalIgnoreCase))
                    .ToList();

                if (matchingClaims.Count == 0)
                {
                    var claim = new AppUserClaim
                    {
                        ClaimId = Guid.NewGuid(),
                        UserId = gustavo.UserId,
                        ClaimType = claimType,
                        ClaimValue = "true"
                    };
                    context.Claims.Add(claim);
                    gustavoClaims.Add(claim);
                    claimsChanged = true;
                    continue;
                }

                foreach (var claim in matchingClaims.Where(claim => claim.ClaimValue != "true"))
                {
                    claim.ClaimValue = "true";
                    claimsChanged = true;
                }
            }

            if (claimsChanged)
            {
                await context.SaveChangesAsync();
            }
        }



